//! Cross-language interop: packages produced and signed by Python `ego_pod` v0.2
//! (multi-edition lite/normal/plus, deep grid L1..L3) must verify in FayGer's
//! Rust loader. Fixtures are regenerated by `tests/fixtures/ego_v0_2/regenerate.py`.

#![allow(
    missing_docs,
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::panic,
    clippy::missing_const_for_fn
)]

use fayger_cli::ego_package::{verify_and_mount_ego_package, FidelityGatePolicy};
use std::fs;
use std::path::{Path, PathBuf};

fn fixture_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/ego_v0_2")
}

fn read_trimmed(name: &str) -> String {
    fs::read_to_string(fixture_root().join(name))
        .expect("fixture file")
        .trim()
        .to_owned()
}

fn plus_cells(pkg: &Path) -> Vec<String> {
    let manifest: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(pkg.join("manifest.json")).unwrap()).unwrap();
    manifest["integrity"]["cell_digests"]
        .as_object()
        .unwrap()
        .keys()
        .filter(|k| k.starts_with("plus/"))
        .cloned()
        .collect()
}

fn copy_dir(src: &Path, dst: &Path) {
    fs::create_dir_all(dst).unwrap();
    for entry in fs::read_dir(src).unwrap() {
        let entry = entry.unwrap();
        let to = dst.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_dir(&entry.path(), &to);
        } else {
            fs::copy(entry.path(), &to).unwrap();
        }
    }
}

#[test]
fn ego_v0_2_multi_edition_package_verifies_fully_and_per_edition() {
    let pkg = fixture_root().join("stub-measured");
    let (fay, key) = (
        read_trimmed("signer_fay_id.txt"),
        read_trimmed("trusted_pubkey.hex"),
    );
    let policy = FidelityGatePolicy::permissive_offline();

    let all = verify_and_mount_ego_package(&pkg, &fay, &key, &[], &policy).expect("full mount");
    assert_eq!(
        all.mounted_cells.len(),
        15,
        "lite 3 + normal 5 + plus 7 cells"
    );

    let plus = plus_cells(&pkg);
    assert_eq!(
        plus.len(),
        7,
        "plus edition carries Kernel + L1..L3 in two zones"
    );
    let sub = verify_and_mount_ego_package(&pkg, &fay, &key, &plus, &policy).expect("plus mount");
    assert_eq!(sub.mounted_cells.len(), 7);
}

#[test]
fn stub_package_without_consistency_score_is_rejected_by_production_policy() {
    let pkg = fixture_root().join("stub-measured");
    let (fay, key) = (
        read_trimmed("signer_fay_id.txt"),
        read_trimmed("trusted_pubkey.hex"),
    );
    let err = verify_and_mount_ego_package(
        &pkg,
        &fay,
        &key,
        &[],
        &FidelityGatePolicy::production_default(),
    )
    .expect_err("stub package must not pass production gate");
    assert!(
        format!("{err:?}").contains("MissingCellConsistencyScore"),
        "{err:?}"
    );
}

#[test]
fn package_with_measured_consistency_passes_production_policy() {
    // gate-ready fidelity numbers are synthetic; this checks the contract, not model quality.
    let pkg = fixture_root().join("gate-ready");
    let (fay, key) = (
        read_trimmed("signer_fay_id.txt"),
        read_trimmed("trusted_pubkey.hex"),
    );
    let mount = verify_and_mount_ego_package(
        &pkg,
        &fay,
        &key,
        &[],
        &FidelityGatePolicy::production_default(),
    )
    .expect("re-signed package with consistency score must pass production gate");
    assert_eq!(mount.fidelity_status, "measured");
}

#[test]
fn wrong_key_and_tampered_deep_cell_are_rejected() {
    let src = fixture_root().join("stub-measured");
    let (fay, key) = (
        read_trimmed("signer_fay_id.txt"),
        read_trimmed("trusted_pubkey.hex"),
    );
    let policy = FidelityGatePolicy::permissive_offline();

    assert!(verify_and_mount_ego_package(&src, &fay, &"00".repeat(32), &[], &policy).is_err());

    let tmp = std::env::temp_dir().join(format!("fayger-ego-tamper-{}", std::process::id()));
    let _ = fs::remove_dir_all(&tmp);
    copy_dir(&src, &tmp);
    let deep = tmp.join("plus/adapters/coding/L3.safetensors");
    let mut bytes = fs::read(&deep).unwrap();
    *bytes.last_mut().unwrap() ^= 1;
    fs::write(&deep, bytes).unwrap();
    let err = verify_and_mount_ego_package(&tmp, &fay, &key, &[], &policy)
        .expect_err("tampered L3 cell must be rejected");
    let _ = fs::remove_dir_all(&tmp);
    assert!(format!("{err:?}").contains("LdrDigestMismatch"), "{err:?}");
}
